create_table:
CREATE TABLE admin_dashboard_summary (
  total_faculty bigint,
  total_students bigint,
  total_sessions bigint
);

CREATE TABLE categories (
  name text NOT NULL,
  id uuid NOT NULL DEFAULT uuid_generate_v4(),
  course_id uuid,
  created_at timestamp without time zone DEFAULT now()
);

CREATE TABLE course_enrollments (
  id uuid NOT NULL DEFAULT uuid_generate_v4(),
  enrolled_at timestamp without time zone DEFAULT now(),
  student_id uuid,
  course_id uuid
);

CREATE TABLE faculty_monthly_hours (
  hours numeric,
  faculty_id uuid,
  sessions bigint,
  month timestamp with time zone
);

CREATE TABLE session_skills (
  session_id uuid NOT NULL,
  skill_id uuid NOT NULL
);

CREATE TABLE session_types (
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  name text NOT NULL,
  created_at timestamp without time zone DEFAULT now()
);

CREATE TABLE student_attendance_summary (
  student_id uuid,
  attendance_percentage numeric
);

CREATE TABLE wifi_snapshots (
  id bigint NOT NULL DEFAULT nextval('wifi_snapshots_id_seq'::regclass),
  captured_at timestamp with time zone NOT NULL,
  iw_dump jsonb NOT NULL,
  error text
);
